import { ref, reactive } from 'vue'
import { message } from 'ant-design-vue'

/**
 * Settings state + debounced auto-save backed by config.yaml.
 *
 * Bindings (auto-generated by Wails in bridge/go/main/ByteGitApp.js):
 *   SettingsGet()    -> SettingsDTO
 *   SettingsSave(patch: { [dotPath]: string }) -> void
 *   SettingsReload() -> SettingsDTO
 */
export interface SettingsDTO {
  model: string
  baseUrl: string
  apiKey: string
  lang: string
  maxTokens: number
  githubToken: string
  ocrExePath: string
  ocrConcurrency: number
  ocrMaxTools: number
  ocrAudience: string
  ocrLanguage: string
  gitleaksExePath: string
  referenceExePath: string
  rewriteAutoBackup: boolean
  termShellPath: string
  termFontSize: number
  // Feature toggles — control sidebar menu visibility for external-dep features.
  featuresGitHub: boolean
  featuresReference: boolean
  featuresSecret: boolean
  featuresReview: boolean
  configPath: string
}

// dot-path keys mirror the backend applySetting switch
export const SETTING_KEYS = {
  model: 'ai.model',
  baseUrl: 'ai.base_url',
  apiKey: 'ai.api_key',
  lang: 'ai.lang',
  maxTokens: 'ai.max_tokens',
  githubToken: 'github.token',
  ocrExePath: 'ocr.exe_path',
  ocrConcurrency: 'ocr.concurrency',
  ocrMaxTools: 'ocr.max_tools',
  ocrAudience: 'ocr.audience',
  ocrLanguage: 'ocr.language',
  gitleaksExePath: 'gitleaks.exe_path',
  referenceExePath: 'reference.exe_path',
  rewriteAutoBackup: 'rewrite.auto_backup',
  termShellPath: 'terminal.shell_path',
  termFontSize: 'terminal.font_size',
  featuresGitHub: 'features.github',
  featuresReference: 'features.reference',
  featuresSecret: 'features.secret',
  featuresReview: 'features.review',
} as const

type App = {
  SettingsGet(): Promise<SettingsDTO>
  SettingsSave(patch: Record<string, string>): Promise<void>
  SettingsReload(): Promise<SettingsDTO>
}

const getApp = (): App | undefined => (window as any).go?.main?.ByteGitApp

// shared reactive state
const settings = reactive<SettingsDTO>({
  model: '',
  baseUrl: '',
  apiKey: '',
  lang: 'zh',
  maxTokens: 4000,
  githubToken: '',
  ocrExePath: '',
  ocrConcurrency: 0,
  ocrMaxTools: 0,
  ocrAudience: 'agent',
  ocrLanguage: '',
  gitleaksExePath: '',
  referenceExePath: '',
  rewriteAutoBackup: false,
  termShellPath: '',
  termFontSize: 13,
  featuresGitHub: false,
  featuresReference: false,
  featuresSecret: false,
  featuresReview: false,
  configPath: '',
})
const loaded = ref(false)
const loading = ref(false)
const saving = ref(false)

// pending dot-path patches keyed by field, flushed after debounce
let pendingPatch: Record<string, string> = {}
let flushTimer: ReturnType<typeof setTimeout> | null = null
let lastError: string | null = null

async function flushSave() {
  const app = getApp()
  if (!app || Object.keys(pendingPatch).length === 0) return
  const patch = { ...pendingPatch }
  pendingPatch = {}
  saving.value = true
  try {
    await app.SettingsSave(patch)
    message.success('已保存', 1.5)
    lastError = null
  } catch (e: any) {
    lastError = String(e?.message || e)
    message.error(`保存失败: ${lastError}`)
  } finally {
    saving.value = false
  }
}

/**
 * Queue a debounced save for one field.
 * @param key  dot-path (use SETTING_KEYS)
 * @param value string form (numbers are coerced by the backend)
 */
function queueSave(key: string, value: string | number) {
  pendingPatch[key] = String(value)
  if (flushTimer) clearTimeout(flushTimer)
  flushTimer = setTimeout(flushSave, 300)
}

async function load() {
  const app = getApp()
  if (!app) return
  loading.value = true
  try {
    const dto = await app.SettingsGet()
    Object.assign(settings, dto)
    loaded.value = true
  } catch (e: any) {
    message.error(`加载配置失败: ${e?.message || e}`)
  } finally {
    loading.value = false
  }
}

async function reload() {
  const app = getApp()
  if (!app) return
  // cancel any pending edits before discarding
  if (flushTimer) {
    clearTimeout(flushTimer)
    flushTimer = null
  }
  pendingPatch = {}
  loading.value = true
  try {
    const dto = await app.SettingsReload()
    Object.assign(settings, dto)
    message.success('已重置为磁盘配置', 1.5)
  } catch (e: any) {
    message.error(`重置失败: ${e?.message || e}`)
  } finally {
    loading.value = false
  }
}

export function useSettings() {
  return {
    settings,
    loaded,
    loading,
    saving,
    load,
    reload,
    queueSave,
  }
}

/**
 * Feature flags — convenience computed wrappers over the settings booleans.
 *
 * These gate sidebar menu visibility for external-dependency features.
 * Default false (clean menu for new users); existing users with token/exe
 * config get auto-enabled by the backend's migrateFeatures on first load.
 *
 * Usage in Sidebar: `const { githubEnabled } = useFeatureFlags()`
 * Usage in forms:   `:checked="githubEnabled" @change="toggle('features.github', $event)"`
 */
import { computed } from 'vue'

const githubEnabled = computed(() => settings.featuresGitHub)
const referenceEnabled = computed(() => settings.featuresReference)
const secretEnabled = computed(() => settings.featuresSecret)
const reviewEnabled = computed(() => settings.featuresReview)

export function useFeatureFlags() {
  return {
    githubEnabled,
    referenceEnabled,
    secretEnabled,
    reviewEnabled,
  }
}
